"""Document completed negative pure-model experiments; never deploy models or slides."""
import json,subprocess,sys,hashlib,shutil
from pathlib import Path
import xml.etree.ElementTree as ET
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def main():
 run=ROOT/'reports/pure_recall_mixup_20261108';parent=ROOT/'reports/pure_recall_recovery_v2_20261108';decision=read(run/'deployment_decision.json')
 assert not decision['eligible'] and not decision['test_evaluated'],'This report finalizes negative results only; qualifying models require a separate integration review.'
 subprocess.run([sys.executable,'-m','scripts.report_recall_recovery'],cwd=ROOT,check=True)
 doc=ROOT/'PURE_RECALL_RECOVERY_RESULTS.md';s=doc.read_text(encoding='utf-8');rows=read(run/'head_history.json');offset=max(r['epoch'] for r in read(run/'initial_history.json'))
 lines=['','## Conditional native-classifier feature-mixup experiment','',f"Completed {len(rows)} classifier-only epochs across four independent recipes. No validation checkpoint passed all requirements; no new test candidate was evaluated. This phase ran only after the earlier round produced no qualifying candidate and used no new test. It reused the deployed pure backbone; failed full-network candidates are not its ancestors.",'', 'Training interpolates two TRAIN feature vectors and class targets, using 75% mixed-target CE, 25% unmixed CE and correct positive/negative TRAIN disgust-boundary retention from the same pure classifier. The reference is discarded for inference. No external encoder, inference probability ensemble or class offset is used. This is classifier-only regularization, not new backbone feature learning.','', 'This frozen-feature adaptation is inspired by [Verma et al., Manifold Mixup, ICML 2019](https://proceedings.mlr.press/v97/verma19a.html), not an exact reproduction of joint hidden-representation training. Interpolated TRAIN features create no new subjects. Validation/test images are real, unchanged and unfiltered.','', '| Best feasibility validation checkpoint per recipe | Epochs | Accuracy | Macro F1 | Disgust P/R/F1 | Happy recall | Surprise recall | Neutral recall | Meets gates |','|---|---:|---:|---:|---|---:|---:|---:|---|']
 for recipe in read(run/'protocol.json')['recipes']:
  group=[r for r in rows if r['recipe']==recipe['name']];best=max(group,key=lambda r:r['feasibility_objective']);ep=best['epoch']-offset;r=read(run/recipe['name']/f"validation_{ep:02d}_{best['kind']}.json");c=r['classification_report'];d=c['disgust'];lines.append(f"| {recipe['name']} | {len(group)} | {r['accuracy']:.2%} | {c['macro avg']['f1-score']:.4f} | {d['precision']:.4f}/{d['recall']:.2%}/{d['f1-score']:.4f} | {c['happy']['recall']:.2%} | {c['surprise']['recall']:.2%} | {c['neutral']['recall']:.2%} | {best['eligible']} |")
 active=read(ROOT/'reports/emotion_evaluation.json');c=active['classification_report'];lines+=['','## Latest deployed PURE FusDenseNet test results','',f"Accuracy **{active['accuracy']:.2%}**, macro F1 **{c['macro avg']['f1-score']:.4f}**, all {active['n']} retained test faces. These are unchanged existing results, not a newly evaluated candidate.",'','| Class | Recall | Support |','|---|---:|---:|']
 for name in ['angry','disgust','fear','happy','sad','surprise','neutral']:lines.append(f"| {name} | {c[name]['recall']:.2%} | {int(c[name]['support'])} |")
 protected={n:hashlib.sha256((ROOT/n).read_bytes()).hexdigest()==h for n,h in read(run/'protected_artifacts.json').items()};assert all(protected.values())
 suites=ET.parse(ROOT/'reports/recall_recovery_all_tests.xml').getroot();nodes=[suites] if suites.tag=='testsuite' else list(suites);summary={k:sum(float(n.get(k,0)) for n in nodes) for k in ['tests','failures','errors','skipped','time']}
 lines+=['',f'Final software tests: {summary}. All seven protected model/app/report/PPT hashes remain unchanged. App and PPT were not updated because no candidate met the requested improvement conditions.','', 'All failed recipe histories, student/EMA reports, exact source snapshots and decision JSON are retained. Historical validation/test reuse limits independent confirmation. No physiological, weather, therapeutic or sensor improvement is claimed.']
 doc.write_text(s+'\n'.join(lines)+'\n',encoding='utf-8')
 baseline=read(run/'current_validation.json');b=baseline['classification_report'];base=[baseline['accuracy'],b['macro avg']['f1-score'],b['disgust']['recall'],b['happy']['recall'],b['surprise']['recall'],b['neutral']['recall']];keys=['val_accuracy','val_macro_f1','val_disgust_recall','val_happy_recall','val_surprise_recall','val_neutral_recall'];fig,axes=plt.subplots(2,3,figsize=(16,8))
 for ax,key,bv in zip(axes.flat,keys,base):
  for recipe in read(run/'protocol.json')['recipes']:
   group=[r for r in rows if r['recipe']==recipe['name']];ax.plot(range(1,len(group)+1),[r[key] for r in group],label=recipe['name'])
  ax.axhline(bv,color='black',linestyle='--');ax.set(title=key.replace('_',' '),xlabel='Independent classifier epoch');ax.grid(alpha=.2)
 axes[0,0].legend(fontsize=7);fig.suptitle('Actual real-image validation: TRAIN-feature mixup recipes, not test results');fig.tight_layout();fig.savefig(run/'mixup_validation_curves.png',dpi=140);plt.close(fig)
 backup=run/'document_backups';backup.mkdir(exist_ok=False)
 for name in ['PROJECT_STATUS.md','EXPERIMENTS.md']:shutil.copy2(ROOT/name,backup/name)
 summary_text=f"# Completed pure FusDenseNet recall-recovery trials - 8 November 2026\n\nTraining finished: 54 corrected classifier recovery epochs, 3 full-network epochs, and {len(rows)} separate feature-mixup classifier epochs. An earlier 21-epoch weighting-error run was interrupted and retained. No new validation candidate met every happy/surprise/neutral recovery and disgust/aggregate retention condition. No new test was evaluated, and app/model/PPT hashes remain unchanged.\n\nActive actual test: accuracy {active['accuracy']:.2%}, macro F1 {c['macro avg']['f1-score']:.4f}, disgust recall {c['disgust']['recall']:.2%} (37/79). This round did not improve the deployed model. The full-network final EMA validation reached 59.07% accuracy but macro F1 0.5383 and disgust recall 32%, so it was rejected.\n\nMeasured deployed-model overfitting: original TRAIN accuracy 92.08% versus validation 58.41%; TRAIN disgust recall 100% versus validation 36%. These gaps are measured, not a proven single-cause diagnosis. Full training changed 113 emotion-path tensors, including 12 attention tensors; changes did not establish a qualifying improvement. All validation faces/classes/errors are retained.\n\nLatest software suite: 94 passed, 15 dependency warnings, 129.35 seconds. Separate report, actual curves and every failure: PURE_RECALL_RECOVERY_RESULTS.md and reports/pure_recall_recovery_v2_20261108/, reports/pure_recall_mixup_20261108/. EEG/HRV results remain unchanged.\n\nEarlier completed records follow.\n\n"
 for name in ['PROJECT_STATUS.md','EXPERIMENTS.md']:
  p=ROOT/name;p.write_text(summary_text+p.read_text(encoding='utf-8'),encoding='utf-8')
 (run/'completion.json').write_text(json.dumps({'reported':True,'decision':decision,'protected_unchanged':protected,'tests':summary},indent=2),encoding='utf-8');print(json.dumps({'report':str(doc),'protected_unchanged':True,'tests':summary},indent=2))
if __name__=='__main__':main()
